import{_ as r,C as n,o as t,c as i,a9 as a,b as d,w as o,a as c,E as l,a8 as h}from"./chunks/framework.BOiBTRPC.js";const y=JSON.parse('{"title":"SQL Deep Dive","description":"Intermediate-to-advanced SQL for data engineers — window functions, query plans, and the analytics patterns that power real pipelines.","frontmatter":{"title":"SQL Deep Dive","description":"Intermediate-to-advanced SQL for data engineers — window functions, query plans, and the analytics patterns that power real pipelines."},"headers":[],"relativePath":"sql/index.md","filePath":"sql/index.md"}'),u={name:"sql/index.md"};function p(g,e,m,f,w,E){const s=n("Mermaid");return t(),i("div",null,[e[1]||(e[1]=a('<h1 id="sql-deep-dive" tabindex="-1">SQL Deep Dive <a class="header-anchor" href="#sql-deep-dive" aria-label="Permalink to &quot;SQL Deep Dive&quot;">​</a></h1><blockquote><p><strong>Why it matters</strong> — SQL is where data correctness and warehouse cost meet. Almost every analytics bug is a SQL bug: silent NULL drops, fanout joins, wrong frame defaults, dedup on the wrong key. Almost every warehouse bill is a SQL problem too: unpruned scans, exploded joins, shuffle storms. This track teaches the 20% of SQL that produces 80% of production outcomes.</p></blockquote><h2 id="who-this-is-for" tabindex="-1">Who this is for <a class="header-anchor" href="#who-this-is-for" aria-label="Permalink to &quot;Who this is for&quot;">​</a></h2><p>You can already write <code>JOIN</code>s, <code>GROUP BY</code>s, and CTEs without thinking. You want the layer senior engineers actually operate at: reading query plans, knowing why a window <code>RANGE</code> frame silently corrupts a running total, writing an SCD2 upsert that survives late-arriving data. Dialects covered are ANSI SQL, BigQuery (GoogleSQL), and Spark SQL — dialect differences are called out where they bite.</p><h2 id="how-the-chapters-fit" tabindex="-1">How the chapters fit <a class="header-anchor" href="#how-the-chapters-fit" aria-label="Permalink to &quot;How the chapters fit&quot;">​</a></h2>',5)),(t(),d(h,null,{default:o(()=>[l(s,{id:"mermaid-17",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22Advanced%20Query%20Craft%3Cbr%2F%3Ewindows%2C%20CTEs%2C%20sets%2C%20NULLs%22%5D%20--%3E%20B%5B%22Query%20Performance%3Cbr%2F%3Eplans%2C%20indexes%2C%20joins%22%5D%0A%20%20%20%20A%20--%3E%20C%5B%22Analytics%20SQL%20Patterns%3Cbr%2F%3Esessions%2C%20cohorts%2C%20SCD2%22%5D%0A%20%20%20%20B%20--%3E%20C%0A%20%20%20%20C%20--%3E%20D%5B%22Senior-level%20SQL%3Cbr%2F%3Ecorrect%20%2B%20fast%20%2B%20maintainable%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="chapters" tabindex="-1">Chapters <a class="header-anchor" href="#chapters" aria-label="Permalink to &quot;Chapters&quot;">​</a></h2><p><strong><a href="/Data-Knowledge/sql/advanced-queries.html">Advanced Query Craft</a></strong> — The constructs that separate intermediate from advanced SQL: window frames (<code>ROWS</code>/<code>RANGE</code>/<code>GROUPS</code>), the <code>LAST_VALUE</code> trap, top-N-per-group, recursive CTEs, <code>LATERAL</code>/<code>UNNEST</code>, set operations, and the NULL semantics that quietly eat rows. Ends with a mental model of logical execution order — <code>QUALIFY</code> vs <code>HAVING</code> vs <code>WHERE</code> — so you stop fighting the grammar and start reasoning about it.</p><p><strong><a href="/Data-Knowledge/sql/query-performance.html">Query Performance</a></strong> — How engines actually execute your query: logical vs physical plans, reading <code>EXPLAIN</code>/<code>EXPLAIN ANALYZE</code>, what B-trees, zone maps, partition pruning, and clustering each buy you, and when hash/merge/broadcast joins win. Then the anti-pattern catalog: <code>SELECT *</code>, functions on join keys, OR-blocked pruning, <code>DISTINCT</code> as a fanout patch, and exploding joins.</p><p><strong><a href="/Data-Knowledge/sql/analytics-patterns.html">Analytics SQL Patterns</a></strong> — The reusable templates of analytics engineering: sessionization via window islands, cohort retention matrices, gaps-and-islands for streaks and missing dates, ASOF joins, dedup that is actually correct, incremental <code>MERGE</code>, date spines, SCD2 built from scratch, and A/B-test aggregation with variance-aware math.</p><h2 id="pareto-focus" tabindex="-1">Pareto focus <a class="header-anchor" href="#pareto-focus" aria-label="Permalink to &quot;Pareto focus&quot;">​</a></h2><p>The ideas in this track that matter most — learn these cold:</p><ol><li><strong>Window frames and the default-frame trap.</strong> <code>RANGE UNBOUNDED PRECEDING</code> plus peers silently duplicates values. Know the default, always specify the frame.</li><li><strong><code>ROW_NUMBER()</code> + <code>QUALIFY</code> is the dedup primitive.</strong> Almost every &quot;latest record&quot; and &quot;top-N-per-group&quot; question is this pattern in a trench coat.</li><li><strong>Logical execution order.</strong> <code>FROM → WHERE → GROUP BY → HAVING → SELECT → QUALIFY → DISTINCT → ORDER BY → LIMIT</code>. Every confusing error message is this order made visible.</li><li><strong>NULL is three-valued logic.</strong> <code>NOT IN</code> + NULL = empty result. <code>=</code> never matches NULL. Outer-join column NULLs break <code>WHERE</code> filters.</li><li><strong>Read the plan, not the query.</strong> Row-count estimates vs actuals in <code>EXPLAIN ANALYZE</code> reveal where the optimizer guessed wrong — that&#39;s where your time goes.</li><li><strong>Prune before you shuffle.</strong> Filter and project early; joins multiply data, filters divide it. On columnar warehouses, <code>WHERE</code> on the partition/cluster key is the single biggest cost lever.</li><li><strong>Islands solve sequences.</strong> Sessionization, streaks, missing dates — the two-<code>ROW_NUMBER</code> islands trick handles all of them without self-joins.</li><li><strong>MERGE is a contract, not magic.</strong> An incremental upsert that doesn&#39;t handle duplicates, deletes, or out-of-order arrival is a production incident with extra steps.</li></ol>',7))])}const A=r(u,[["render",p]]);export{y as __pageData,A as default};
